def main():
    data=ROOT/'docs/literature/omics-2023-2026';base=ROOT/'build/literature-review/hail-runtime';target=data/'hail-catalog-support.zip';assert not target.exists() and not (data/'hail-catalog-validation.json').exists();render=json.loads((base/'catalog-render-1/COMPLETED.json').read_bytes());gates=json.loads((base/'catalog-scientific-gates-1/COMPLETED.json').read_bytes());ui=json.loads((base/'catalog-ui-2/COMPLETED.json').read_bytes());assert render['status']=='passed-exact-one-Hail-availability-delta-with-eight-reviewed-roles' and len(gates['checks'])==12 and ui['page']==pin(ROOT/'site/literature-review.html') and ui['warning_page']==pin(ROOT/'site/literature-warnings.html');general=json.loads((base/'catalog-ui-2/general/ui-validation.json').read_bytes());focused=json.loads((base/'catalog-ui-2/hail/hail-ui-verification.json').read_bytes());assert general['status']==focused['status']=='passed' and len(general['checks'])==299 and len(focused['checks'])==5 and not focused['page_errors'];before={t['id']:t for t in json.loads((base/'catalog-render-1/before-tool-inventory.json').read_bytes())};current={t['id']:t for t in json.loads((data/'tool-inventory.json').read_bytes())};assert {n for n in before if before[n]!=current[n]}=={'hail'} and len(current)==390;counts=json.loads((data/'summary.json').read_bytes())['implementation_status_counts'];assert (counts['native-subset-validated'],counts['upstream-adapter-validated'],counts['missing'])==(17,66,248)
