    parents={n:pin(ROOT/n) for n in ['docs/literature/hail-workflow-development/VALIDATION.json','docs/literature/hail-workflow-development/controls.zip','docs/literature/omics-2023-2026/biomart-catalog-validation.json','docs/literature/omics-2023-2026/biomart-catalog-support.zip']};proof=json.loads((ROOT/'docs/literature/hail-workflow-development/VALIDATION.json').read_bytes());assert proof['adapter_admitted'];canonical=pin(ROOT/'build/cli/omicsmatic-0.3.7.jar');assert canonical==proof['canonical_executable_unchanged'];held_names=json.loads((ROOT/'build/literature-review/push-checkpoint-2026-11-08-hail-sample-qc-1/selection.json').read_bytes())['preserved'];held={n:pin(ROOT/n) for n in held_names};assert len(held)==18;files['preserved-unrelated-worktree-pins.json']=(json.dumps(held,indent=2)+'\n').encode();packing=pack(target,files);assert target.stat().st_size<95000000;save(data/'hail-catalog-validation.json',dict(schema_version=1,status='passed-eight-Hail-primary-roles-and-one-scoped-integration',archive=pin(target),source_pins=pins,parent_proofs=parents,artifact=proof['artifact'],canonical_executable_unchanged=canonical,new_scoped_integrations=83,including_existing_adapters=86,missing_integrations=248,unrelated_tool_rows_preserved=389,prior_reviews_preserved=952,new_reviews_added=8,reviewed_uses=960,supporting_pointers=331,named_tools=390,observations=2450,general_browser_checks=299,focused_browser_checks=5,scientific_gates=12,website_deployed=False,whole_paper_reproduced=False,whole_goal_complete=False,**packing));hashes={p.name:pin(p)['sha256'] for p in sorted(data.iterdir()) if p.is_file() and p.name!='SHA256SUMS'};order=[line.split('  ',1)[1] for line in (data/'SHA256SUMS').read_text(encoding='utf8').splitlines()];assert len(order)==len(set(order)) and set(order)<=set(hashes);order += [n for n in hashes if n not in set(order)];(data/'SHA256SUMS').write_bytes(''.join(hashes[n]+'  '+n+'\n' for n in order).encode());assert all(pin(ROOT/n)==v for n,v in pins.items()) and all(pin(ROOT/n)==v for n,v in held.items()) and pin(ROOT/'build/cli/omicsmatic-0.3.7.jar')==canonical
    from verify_hail_catalog import verify
